@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Gather all vertices supplied in the resultMap
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if (n < 2) {
        return; // Not enough vertices to form a bipartite graph
    }
    // Arbitrarily split the list into two parts
    int split = n / 2;
    List<V> left = vertices.subList(0, split);
    List<V> right = vertices.subList(split, n);
    // Add edges between every pair of vertices from different parts
    for (V u : left) {
        for (V v : right) {
            // Assuming the graph API accepts a null edge value for simple graphs
            target.addEdge(u, v, null);
        }
    }
    // Optionally keep reference vertices in the resultMap for other components
    if (!left.isEmpty()) {
        resultMap.put("sampleLeft", left.get(0));
    }
    if (!right.isEmpty()) {
        resultMap.put("sampleRight", right.get(0));
    }
}

