@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
  List<V> left = new ArrayList<>();
  List<V> right = new ArrayList<>();
  for (Map.Entry<String,V> entry : resultMap.entrySet()){
    String key = entry.getKey().toLowerCase();
    if (key.contains("left")){
      left.add(entry.getValue());
    } else if (key.contains("right")){
      right.add(entry.getValue());
    }
  }
  for (V v : left) target.addVertex(v);
  for (V v : right) target.addVertex(v);
  for (V u : left){
    for (V v : right){
      target.addEdge(u, v);
    }
  }
}

public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    int leftSize = 2;
    int rightSize = 2;
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (int i = 0; i < leftSize; i++) {
        V v = target.addVertex();
        left.add(v);
        resultMap.put("L" + i, v);
    }
    for (int i = 0; i < rightSize; i++) {
        V v = target.addVertex();
        right.add(v);
        resultMap.put("R" + i, v);
    }
    for (V lv : left) {
        for (V rv : right) {
            target.addEdge(lv, rv);
        }
    }
}

