public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int size = schema.serializedSize(message);
    // write the length as a varint
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeUInt32NoTag(size);
    // serialize the message into the buffer
    schema.writeTo(buffer, message);
    // flush buffer contents to the output stream
    buffer.flushTo(out);
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Compute serialized size of the message
    int size = schema.getCachedSize(message);

    // Encode the size as a varint and write it to the stream
    byte[] sizeBuf = new byte[10];
    int pos = 0;
    int v = size;
    while ((v & ~0x7F) != 0) {
        sizeBuf[pos++] = (byte)((v & 0x7F) | 0x80);
        v >>>= 7;
    }
    sizeBuf[pos++] = (byte)v;
    out.write(sizeBuf, 0, pos);

    // Encode the message into the buffer
    buffer.clear();
    schema.writeTo(buffer, message);

    // Write the encoded bytes to the stream
    out.write(buffer.start(), buffer.writePosition());

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int size = schema.calculateSize(message);
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeUInt32NoTag(size);
    cos.flush();
    schema.write(message, buffer);
    out.write(buffer.getBuffer(), 0, buffer.getSize());
    buffer.clear();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int rawSize = schema.getSerializedSize(message, buffer);
    int lengthPrefixSize = CodedOutputStream.computeRawVarint32Size(rawSize);
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(rawSize);
    schema.writeTo(message, cos);
    cos.flush();
    return rawSize + lengthPrefixSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Allocate a buffer big enough for the encoded message plus varint length prefix
    ByteBuf buf = Unpooled.buffer(schema.encodedLength(message) + 5);
    // Encode the message into the buffer using the provided schema and temporary buffer
    schema.writeTo(buf, message, buffer);
    int size = buf.readableBytes();
    // Write the length prefix as a varint to the output stream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Write the actual message bytes
    out.write(buf.array(), buf.arrayOffset() + buf.readerIndex(), size);
    return size;
}

