public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){ 
    if (genericType == null || targetType == null) { 
        return null; 
    } 
    if (!(genericType instanceof ParameterizedType)) { 
        return null; 
    } 
    ParameterizedType pt = (ParameterizedType) genericType; 
    Type[] typeArgs = pt.getActualTypeArguments(); 
    Class<?>[] resolved = new Class[typeArgs.length]; 
    for (int i = 0; i < typeArgs.length; i++) { 
        resolved[i] = resolveRawClass(typeArgs[i], targetType); 
        if (resolved[i] == null) { 
            return null; 
        } 
    } 
    return resolved; 
}

public static Class<?>[] resolveArguments(Type genericType,Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) return null;
    Type[] args = ((ParameterizedType)genericType).getActualTypeArguments();
    Class<?>[] rawArgs = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++){
        Type arg = args[i];
        Class<?> raw;
        if (arg instanceof Class){
            raw = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType){
            raw = (Class<?>) ((ParameterizedType) arg).getRawType();
        } else {
            return null;
        }
        rawArgs[i] = raw;
    }
    return rawArgs;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type arg = typeArguments[i];
        if (arg instanceof Class<?>) {
            result[i] = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class<?>) {
                result[i] = (Class<?>) raw;
            } else {
                return null;
            }
        } else if (arg instanceof TypeVariable<?>) {
            Class<?> resolved = resolveGenericType(arg, targetType);
            if (resolved != null) {
                result[i] = resolved;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
