        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] classes = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        classes[i] = resolveRawClass(args[i], targetType);
        if (classes[i] == null) {
            return null;
        }
    }
    return classes;
}

public static Class<?>[] resolveArguments(java.lang.reflect.Type genericType, Class<?> targetType) {
    if (!(genericType instanceof java.lang.reflect.ParameterizedType)) {
        return null;
    }
    java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) genericType;
    java.lang.reflect.Type[] types = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[types.length];
    java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> varMap = getTypeVariableMap(targetType);
    for (int i = 0; i < types.length; i++) {
        result[i] = resolveRawClass(types[i], targetType, varMap);
        if (result[i] == null) {
            return null;
        }
    }
    return result;
}

private static java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> getTypeVariableMap(Class<?> cls) {
    java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> map = new java.util.HashMap<>();
    Class<?> current = cls;
    while (current != null && current != Object.class) {
        java.lang.reflect.Type generic = current.getGenericSuperclass();
        if (generic instanceof java.lang.reflect.ParameterizedType) {
            java.lang.reflect.Type[] actuals = ((java.lang.reflect.ParameterizedType) generic).getActualTypeArguments();
            java.lang.reflect.TypeVariable<?>[] vars = current.getSuperclass().getTypeParameters();
            for (int j = 0; j < vars.length; j++) {
                map.put(vars[j], actuals[j]);
            }
        }
        current = current.getSuperclass();
    }
    return map;
}

private static Class<?> resolveRawClass(java.lang.reflect.Type t, Class<?> currentCls, java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> varMap) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    } else if (t instanceof java.lang.reflect.TypeVariable<?>) {
        java.lang.reflect.Type mapped = varMap.get((java.lang.reflect.TypeVariable<?>) t);
        if (mapped != null) {
            return resolveRawClass(mapped, currentCls, varMap);
        }
    } else if (t instanceof java.lang.reflect.WildcardType) {
        return Object.class; // fallback
    } else if (t instanceof java.lang.reflect.GenericArrayType) {
        java.lang.reflect.Type comp = ((java.lang.reflect.GenericArrayType) t).getGenericComponentType();
        Class<?> compCls = resolveRawClass(comp, currentCls, varMap);
        if (compCls != null) {
            return java.lang.reflect.Array.newInstance(compCls, 0).getClass();
        }
    }
    return null;
}

