    Mappings current = this.getMapping(tableName);
    if (current == null) {
        return new Mappings();
    }

    // Prepare the result mappings
    Mappings diff = new Mappings();

    // Iterate over fields in the current mapping
    for (Map.Entry<String, Object> field : current.getProperties().entrySet()) {
        String fieldName = field.getKey();

        // Skip the _source field to avoid update conflicts
        if ("_source".equals(fieldName)) {
            continue;
