protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<TimeRange>();
    if (start >= end) {
        return ranges;
    }
    long maxStep = FETCH_DATA_DURATION;
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = currentStart + maxStep;
        if (currentEnd > end) {
            currentEnd = end;
        }
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(end, currentStart + FETCH_DATA_DURATION);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

