    long current = start;
    while (current < end) {
        long next = Math.min(current + maxDuration, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

