public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int count = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            count += 1;
        } else if (ch <= 0x7FF) {
            count += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF && i + 1 < end) {
            char lo = str.charAt(i + 1);
            if (lo >= 0xDC00 && lo <= 0xDFFF) {
                // surrogate pair represents a code point > 0xFFFF
                count += 4;
                i++; // skip low surrogate
            } else {
                // malformed surrogate; treat high surrogate as three bytes
                count += 3;
            }
        } else {
            // Any other non-ASCII character fits in 3 bytes
            count += 3;
        }
    }
    return count;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    int end = Math.min(index + len, str.length());
    int size = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        // handle surrogate pairs
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                int codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
                // code points > U+FFFF are always 4 bytes in UTF‑8
                if (codePoint <= 0xFFFF) {
                    // shouldn't happen for surrogate pair but handle
                    if (codePoint <= 0x7FF) {
                        size += 2;
                    } else {
                        size += 3;
                    }
                } else {
                    size += 4;
                }
                i += 2;
                continue;
            }
            // malformed surrogate; treat as replacement character 0xFFFD
            i++;
            size += 3;
            continue;
        }
        // check for low surrogate alone (malformed)
        if (Character.isLowSurrogate(ch)) {
            i++;
            size += 3;
            continue;
        }
        // normal BMP character
        int cp = ch;
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

