public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    for (int i = 0; i < len; ) {
        int cp = str.codePointAt(i);
        int byteCount;
        if (cp <= 0x7F) {
            byteCount = 1;
        } else if (cp <= 0x7FF) {
            byteCount = 2;
        } else if (cp <= 0xFFFF) {
            byteCount = 3;
        } else {
            byteCount = 4;
        }
        lb.ensureCapacity(lb.position() + byteCount);
        if (byteCount == 1) {
            lb.writeByte((byte) cp);
        } else if (byteCount == 2) {
            lb.writeByte((byte) (0xC0 | (cp >> 6)));
            lb.writeByte((byte) (0x80 | (cp & 0x3F)));
        } else if (byteCount == 3) {
            lb.writeByte((byte) (0xE0 | (cp >> 12)));
            lb.writeByte((byte) (0x80 | ((cp >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (cp & 0x3F)));
        } else {
            lb.writeByte((byte) (0xF0 | (cp >> 18)));
            lb.writeByte((byte) (0x80 | ((cp >> 12) & 0x3F)));
            lb.writeByte((byte) (0x80 | ((cp >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (cp & 0x3F)));
        }
        i += Character.charCount(cp);
    }
    return lb;
}

