public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    String[] rawSegments = rawPath.split("/", -1); // keep trailing empty segments
    for (String seg : rawSegments) {
        String value = seg;
        if (decode) {
            try {
                value = URLDecoder.decode(seg, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return result;
    }
    // Remove leading '/' if present (absolute path)
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    if (rawPath.isEmpty()) {
        return result;
    }
    String[] tokens = rawPath.split("/");
    for (String token : tokens) {
        if (token.isEmpty()) {
            continue; // skip empty segments that can appear due to trailing '/'
        }
        String encoded = token;
        String decoded = decode ? URLDecoder.decode(encoded, StandardCharsets.UTF_8) : encoded;
        result.add(new PathSegmentImpl(decoded, encoded));
    }
    return result;
}

