public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int max = desiredCapacity >= 1000
            ? (int) Math.ceil(desiredCapacity * 1.11)
            : Integer.MAX_VALUE;
    for (int n = desiredCapacity; n <= max; n++) {
        if (n == 2) {
            return n;
        }
        if (n % 2 == 0) {
            continue;
        }
        boolean isPrime = true;
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return n;
        }
    }
    // Fallback: return the desiredCapacity if no suitable prime within range
    return desiredCapacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // If desiredCapacity is even, start at next odd number
    if ((candidate & 1) == 0) {
        candidate++;
    }
    int upperBound = desiredCapacity;
    // If capacity >= 1000, limit search to within 11% of desiredCapacity
    if (desiredCapacity >= 1000) {
        upperBound = (int) Math.round(desiredCapacity * 1.11);
    }
    while (candidate <= upperBound) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers
        candidate += 2;
    }
    // If no prime found within the bound, continue searching beyond the bound
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // only odd candidates
    }
}

