            JsonPrimitive prim = element.getAsJsonPrimitive();
            if (prim.isString()){
                map.put(key, prim.getAsString());
            } else if (prim.isNumber()){
                map.put(key, prim.getAsNumber());
            } else if (prim.isBoolean()){
                map.put(key, prim.getAsBoolean());
            } else {
                map.put(key, prim.getAsString());
            }
        } else if (element.isJsonObject()){
            map.put(key, buildContent(element.getAsJsonObject()));
        } else if (element.isJsonArray()){
            map.put(key, element.getAsJsonArray());
        } else if (element.isJsonNull()){
            map.put(key, null);
        }
    }
    if (jsonObject.has("ats") && !jsonObject.get("ats").isJsonNull()){
        map.put("ats", jsonObject.get("ats").getAsString());
    }
    return map;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    // If the JSON contains an "ats" field, explicitly add it to the result map
    if (jsonObject.has("ats")) {
        JsonElement atsElem = jsonObject.get("ats");
        if (atsElem != null && atsElem.isJsonPrimitive()
                && atsElem.getAsJsonPrimitive().isBoolean()) {
            content.put("ats", atsElem.getAsBoolean());
        } else {
            content.put("ats", atsElem);
        }
    }
    // Add all other entries from the JsonObject
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        if (!"ats".equals(entry.getKey())) {
            content.put(entry.getKey(), entry.getValue());
        }
    }
    return content;
}

