private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Begin traversal at the start node in the specified direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Continue until we reach the stop node.
    while (!circ.node().equals(stop)) {
        // Check if the current node satisfies the predicate.
        if (predicate.test(circ.node())) {
            return circ;
        }
        // Move to the next node in the chosen direction.
        circ.next();
    }
    // If the stop node itself satisfies the predicate, return a circulator for it,
    // otherwise simply return a circulator positioned at the stop node.
    if (predicate.test(stop)) {
        return new OuterFaceCirculator(stop, dir);
    } else {
        return new OuterFaceCirculator(stop, dir);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator cursor = new OuterFaceCirculator(start, dir);
    if (predicate.test(cursor.node())) {
        return cursor;
    }
    while (!cursor.node().equals(stop)) {
        cursor = cursor.next();
        if (predicate.test(cursor.node())) {
            return cursor;
        }
    }
    return cursor;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (circ.node() != stop) {
        if (predicate.test(circ.node())) {
            return circ;
        }
        circ.move(dir);
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null || predicate == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }

    // If start equals stop, immediately return a circulator positioned at stop
    if (start.equals(stop)) {
        return new OuterFaceCirculator(stop, dir);
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Traverse until reaching the stop node
    while (!circ.current().equals(stop)) {
        if (predicate.test(circ.current())) {
            return circ;
        }
        circ.advance(dir);
    }

    // If the predicate never matched, return a circulator to the stop node
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        if (current == stop) {
            return new OuterFaceCirculator(stop);
        }
        current = dir == 1 ? current.getSuccessor() : current.getPredecessor();
    }
}

