@Override public Action inspect(AtmosphereResource r){
    if (r == null) return Action.CONTINUE;
    // Automatically suspend the resource based on the transport type
    switch (r.getTransport()) {
        case WEBSOCKET:
            r.suspend(0); // keep alive forever
            break;
        case LONG_POLLING:
            r.suspend(5000); // suspend long polling after 5 seconds
            break;
        default:
            // for other transports no suspension
    }
    return Action.CONTINUE;
}

