protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    // Map from source vertex to edge starting at that vertex
    java.util.Map<V, E> fromMap = new java.util.HashMap<>();
    // Map from target vertex to edge ending at that vertex
    java.util.Map<V, E> toMap = new java.util.HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        fromMap.put(src, e);
        toMap.put(tgt, e);
    }
    // Find starting vertex (vertex that is source but not target)
    V start = null;
    for (V v : fromMap.keySet()) {
        if (!toMap.containsKey(v)) {
            start = v;
            break;
        }
    }
    // If not found (e.g., a cycle), pick any source
    if (start == null) {
        start = fromMap.keySet().iterator().next();
    }
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    V current = start;
    while (edgeList.size() < tour.size()) {
        E e = fromMap.get(current);
        if (e == null) {
            // Inconsistent tour; cannot build path
            return null;
        }
        edgeList.add(e);
        vertexList.add(current);
        current = graph.getEdgeTarget(e);
    }
    vertexList.add(current);
    // Compute total weight of the path
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Map each vertex to the list of incident edges still to be processed
    Map<V, List<E>> adj = new HashMap<>();

    for (E e : tour) {
        V v1 = graph.getEdgeSource(e);
        V v2 = graph.getEdgeTarget(e);
        adj.computeIfAbsent(v1, k -> new ArrayList<>()).add(e);
        adj.computeIfAbsent(v2, k -> new ArrayList<>()).add(e);
    }

    List<E> pathEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, pathVertices, pathEdges, 0.0);
    }

    // Start from an arbitrary edge's source vertex
    V current = graph.getEdgeSource(tour.iterator().next());
    pathVertices.add(current);

    while (true) {
        List<E> edges = adj.get(current);
        if (edges == null || edges.isEmpty()) {
            break; // no more edges from current vertex
        }
        E nextEdge = edges.remove(0); // take one of the incident edges
        pathEdges.add(nextEdge);

        // Find the other vertex of this edge
        V next = graph.getEdgeTarget(nextEdge);
        if (next.equals(current)) {
            next = graph.getEdgeSource(nextEdge);
        }

        // Remove the used edge from the opposite vertex's list
        List<E> otherList = adj.get(next);
        if (otherList != null) {
            otherList.remove(nextEdge);
        }

        current = next;
        pathVertices.add(current);
    }

    // Compute total path weight
    double weight = 0.0;
    for (E e : pathEdges) {
        weight += graph.getEdgeWeight(e);
    }

    return new GraphPathImpl<>(graph, pathVertices, pathEdges, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    List<E> edgeList = new ArrayList<>(tour);
    double weight = 0.0;
    for (E e : tour) {
        weight += graph.getEdgeWeight(e);
    }
    V source = null;
    V target = null;
    if (!edgeList.isEmpty()) {
        E firstEdge = edgeList.get(0);
        source = graph.getEdgeSource(firstEdge);
        E lastEdge = edgeList.get(edgeList.size() - 1);
        target = graph.getEdgeTarget(lastEdge);
    }
    return new GraphWalk<>(graph, source, target, edgeList, weight);
}

