private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // Adjust previous node's next reference
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        first = node.next;
    }
    // Adjust next node's prev reference
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        last = node.prev;
    }
    // Clear references in the removed node
    node.prev = null;
    node.next = null;
    // Decrement the size counter
    size--;
    return true;
}

