private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int n = bounds.size();
    List<Integer> suffixList = new ArrayList<>(n);
    long suffixSum = 0;
    long totalSum = 0;
    for(int i = n - 1; i >= 0; i--){
        int val = bounds.get(i);
        suffixSum += val;
        suffixList.add(0, (int) suffixSum);
        totalSum += val;
    }
    return new Pair<>(suffixList, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffix.add(0, (int) sum);
    }
    return new Pair<>(suffix, sum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    long sumAll = 0L;
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long suffixSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffix.add(0, (int) suffixSum);
        sumAll = suffixSum;
    }
    return Pair.of(suffix, sumAll);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    long suffixSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffix.add(0, (int) suffixSum);
    }
    for (int val : bounds) {
        total += val;
    }
    return Pair.of(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    while (from < to) {
        V tmp = arr[from];
        arr[from] = arr[to];
        arr[to] = tmp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    synchronized(this){
        synchronized(list){
            if (list.first == null) return;
            if (this.first == null){
                this.first = list.first;
                this.last = list.last;
            } else {
                this.last.next = list.first;
                list.first.prev = this.last;
                this.last = list.last;
            }
            this.size += list.size;
            list.first = null;
            list.last = null;
            list.size = 0;
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this || list.size == 0) {
        return;
    }
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    this.size += list.size;
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Continuously remove the first node from the source list and add it to this list
    // until the source list is empty.
    while (!list.isEmpty()) {
        ListNode<E> node = list.getFirst();
        list.removeListNode(node);
        addListNode(node);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        return;
    }
    // Move nodes one by one until the source list is empty
    ListNodeImpl<E> node = list.getFirstNode();
    while (node != null) {
        // Remove the node from the source list
        list.removeListNode(node);
        // Add the node to the current list
        this.addListNode(node);
        // Advance to the next node in the source list
        node = list.getFirstNode();
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    synchronized (this) {
        synchronized (list) {
            ListNode<E> node = list.head;
            while (node != null) {
                ListNode<E> next = node.next;
                list.removeListNode(node);
                this.addListNode(node);
                node = next;
            }
        }
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) return prefix == null;
    if (prefix == null) return false;
    if (prefix.length() > str.length()) return false;
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }
    int len = prefix.length();
    if (len > str.length()) {
        return false;
    }
    if (!ignoreCase) {
        return str.startsWith(prefix);
    }
    for (int i = 0; i < len; i++) {
        char c1 = str.charAt(i);
        char c2 = prefix.charAt(i);
        if (Character.toLowerCase(c1) != Character.toLowerCase(c2)) {
            return false;
        }
    }
    return true;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    if (prefix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null && prefix == null) {
        return true;
    }
    if (str == null || prefix == null) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if (str == null) return prefix == null;
    if (prefix == null) return false;
    int len = prefix.length();
    if (len > str.length()) return false;
    return ignoreCase ? str.regionMatches(true, 0, prefix, 0, len)
                      : str.startsWith(prefix);
}

