public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) return path;
    boolean leadingSlash = path.startsWith("/");
    String[] pathParts = path.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.removeLast();
        } else {
            stack.addLast(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.removeLast();
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder result = new StringBuilder();
    if (leadingSlash) result.append("/");
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) result.append("/");
    }
    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if(path==null) throw new IllegalArgumentException("path cannot be null");
    if(relativePath==null) return path;
    if(relativePath.startsWith("/")) return relativePath;
    java.io.File combined = new java.io.File(path, relativePath);
    try{
        return combined.getCanonicalPath();
    }catch(java.io.IOException e){
        return combined.getPath();
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    java.util.List<String> stack = new java.util.ArrayList<>();

    boolean absolute = path.startsWith("/");
    String[] pathParts = path.split("/");

    for (int i = 0; i < pathParts.length; i++) {
        String part = pathParts[i];
        if (part.isEmpty() && i == 0) {
            // leading slash for absolute paths; ignore
            continue;
        }
        // If the original path does not end with a slash, treat the last segment as a file and skip it
        if (i == pathParts.length - 1 && !path.endsWith("/")) {
            break;
        }
        stack.add(part);
    }

